List<List<Integer>> palindromePairs(String[] words) {
  Map<String, Integer> index = new HashMap<>();
  for (int i = 0; i < words.length; i++) index.put(words[i], i);
  List<List<Integer>> out = new ArrayList<>();
  for (int i = 0; i < words.length; i++) for (int cut = 0; cut <= words[i].length(); cut++) {
    String left = words[i].substring(0, cut), right = words[i].substring(cut);
    String revRight = new StringBuilder(right).reverse().toString();
    String revLeft = new StringBuilder(left).reverse().toString();
    if (isPal(left) && index.containsKey(revRight) && index.get(revRight) != i) out.add(List.of(index.get(revRight), i));
    if (cut != words[i].length() && isPal(right) && index.containsKey(revLeft) && index.get(revLeft) != i) out.add(List.of(i, index.get(revLeft)));
  }
  return out;
}
boolean isPal(String s) { return new StringBuilder(s).reverse().toString().equals(s); }

