class FsNode { children = new Map<string, FsNode>(); content?: string; }
export class FileSystem {
  private root = new FsNode();
  private walk(path: string): FsNode {
    let node = this.root;
    for (const part of path.split('/').filter(Boolean)) {
      if (!node.children.has(part)) node.children.set(part, new FsNode());
      node = node.children.get(part)!;
    }
    return node;
  }
  ls(path: string): string[] { const node = this.walk(path); return node.content === undefined ? [...node.children.keys()].sort() : [path.split('/').pop()!]; }
  mkdir(path: string): void { this.walk(path); }
  addContent(path: string, content: string): void { const node = this.walk(path); node.content = (node.content ?? '') + content; }
  readContent(path: string): string { return this.walk(path).content ?? ''; }
}

java.code:
class FileSystem {
  static class Node { Map<String, Node> children = new TreeMap<>(); StringBuilder content; }
  private final Node root = new Node();
  private Node walk(String path) {
    Node node = root;
    for (String part : path.split("/")) if (!part.isEmpty()) node = node.children.computeIfAbsent(part, k -> new Node());
    return node;
  }
  List<String> ls(String path) { Node node = walk(path); return node.content != null ? List.of(path.substring(path.lastIndexOf('/') + 1)) : new ArrayList<>(node.children.keySet()); }
  void mkdir(String path) { walk(path); }
  void addContent(String path, String content) { Node node = walk(path); if (node.content == null) node.content = new StringBuilder(); node.content.append(content); }
  String readContent(String path) { Node node = walk(path); return node.content == null ? "" : node.content.toString(); }
}

