from collections import deque

def num_islands_bfs(grid):
    rows, cols = len(grid), len(grid[0])
    seen = set()
    islands = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '1' or (r, c) in seen:
                continue
            islands += 1
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                cr, cc = queue.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    valid = 0 <= nr < rows and 0 <= nc < cols
                    if valid and grid[nr][nc] == '1' and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
    return islands

typescript.code:
export function numIslandsBfs(grid: string[][]): number {
  const rows = grid.length, cols = grid[0].length;
  const seen = new Set<string>();
  const key = (r: number, c: number) => `${r},${c}`;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let islands = 0;
  for (let r = 0; r < rows; r += 1) for (let c = 0; c < cols; c += 1) {
    if (grid[r][c] !== '1' || seen.has(key(r, c))) continue;
    islands += 1;
    const queue: Array<[number, number]> = [[r, c]];
    seen.add(key(r, c));
    for (let head = 0; head < queue.length; head += 1) {
      const [cr, cc] = queue[head];
      for (const [dr, dc] of dirs) {
        const nr = cr + dr, nc = cc + dc;
        const valid = nr >= 0 && nr < rows && nc >= 0 && nc < cols;
        if (valid && grid[nr][nc] === '1' && !seen.has(key(nr, nc))) {
          seen.add(key(nr, nc));
          queue.push([nr, nc]);
        }
      }
    }
  }
  return islands;
}

