export function shortestPath(grid: number[][]): number {
  const n = grid.length;
  if (grid[0][0] || grid[n - 1][n - 1]) return -1;
  const queue: Array<[number, number, number]> = [[0, 0, 1]];
  const seen = new Set<string>(['0,0']);
  for (let head = 0; head < queue.length; head += 1) {
    const [r, c, distance] = queue[head];
    if (r === n - 1 && c === n - 1) return distance;
    for (let dr = -1; dr <= 1; dr += 1) for (let dc = -1; dc <= 1; dc += 1) {
      const nr = r + dr, nc = c + dc, key = `${nr},${nc}`;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] === 0 && !seen.has(key)) {
        seen.add(key); queue.push([nr, nc, distance + 1]);
      }
    }
  }
  return -1;
}

